const $=s=>document.querySelector(s), app=$('#app'), peso=n=>`₱${n.toLocaleString('en-PH')}`, img=r=>`/images/rooms/${r.image}`, href=r=>`/rooms/${r.slug}/`, book=r=>`/booking/?room=${r.slug}`;
const icon=(name)=>({users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M17 5a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 5"/>',arrow:'<path d="M4 12h16m-7-7 7 7-7 7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="1"/><path d="M7 3v4m10-4v4M3 10h18"/>',check:'<path d="m4 12 5 5L20 6"/>'})[name];
const svg=n=>`<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${icon(n)}</svg>`;
function shell(content){app.innerHTML=`<header class="site-header"><a class="brand" href="/" aria-label="Aquapoint Beach Resort home"><span class="brand-mark">A</span><span>AQUAPOINT<small>BEACH RESORT</small></span></a><nav aria-label="Main navigation"><a href="/">Home</a><a href="/rooms/">Rooms & Stays</a><a href="/booking/">Reservations</a></nav><a class="header-cta" href="/rooms/">Explore Rooms ${svg('arrow')}</a></header><main>${content}</main><footer><div><span class="eyebrow">AQUAPOINT BEACH RESORT</span><h2>Your Relaxing Escape<br>by the Sea.</h2></div><div><a href="/rooms/">Explore rooms</a><a href="/booking/">Plan your stay</a><p>Rates shown are estimates. Reservations are confirmed by resort staff.</p></div></footer>`}
function card(r){return `<article class="room-card"><a class="card-image" href="${href(r)}"><img src="${img(r)}" alt="${r.name} accommodation at Aquapoint Beach Resort" loading="lazy"></a><div class="card-body"><div class="card-top"><span class="eyebrow">${r.category}</span><span class="capacity">${svg('users')}${r.capacity?`Up to ${r.capacity} Guests`:'Capacity on request'}</span></div><h3><a href="${href(r)}">${r.name}</a></h3><p>${r.description}</p><div class="card-bottom"><span>${r.price?`<b>${peso(r.price)}</b> / night`:'Rate on request'}</span><a href="${href(r)}" aria-label="${r.cta}: ${r.name}">VIEW ROOM ${svg('arrow')}</a></div></div></article>`}
function home(){shell(`<section class="home-hero"><img src="${img(rooms[8])}" alt="Aquapoint Luxury Villa" class="hero-photo"><div class="hero-shade"></div><div class="hero-copy"><span class="eyebrow light">AQUAPOINT BEACH RESORT</span><h1>Make room for<br><em>the coast.</em></h1><p>Your relaxing escape by the sea. Find the space that fits your kind of getaway.</p><a class="button cream" href="/rooms/">EXPLORE OUR STAYS ${svg('arrow')}</a></div><span class="hero-side">PHILIPPINES · BEACH RESORT</span></section><section class="intro"><span class="eyebrow">STAY AT AQUAPOINT</span><div><h2>Find Your<br><em>Perfect Stay</em></h2><p>From intimate rooms for couples to spacious accommodations for families, barkadas, and large groups, discover a stay designed for the way you travel.</p></div></section><section class="featured"><div class="section-head"><span class="eyebrow">THE COLLECTION</span><a href="/rooms/">VIEW ALL STAYS ${svg('arrow')}</a></div><div class="featured-scroll">${rooms.map(card).join('')}</div><div class="center"><a class="button dark" href="/rooms/">EXPLORE ALL ROOMS ${svg('arrow')}</a></div></section><section class="closing"><span class="eyebrow light">YOUR STAY, YOUR WAY</span><h2>Gather together.<br><em>Settle in by the sea.</em></h2><p>From a quiet stay for two to room for the whole group.</p><a class="button cream" href="/rooms/">FIND YOUR ROOM ${svg('arrow')}</a></section>`)}
function listing(){shell(`<section class="page-hero"><span class="eyebrow">ROOMS & ACCOMMODATIONS</span><h1>A Stay for<br><em>Every Escape</em></h1><p>Whether you're traveling as a couple, family, barkada, or large group, find a comfortable space to call your own at Aquapoint Beach Resort.</p></section><section class="listing"><div class="list-toolbar"><div><span class="eyebrow">EXPLORE THE COLLECTION</span><p>Find the space that feels right for you.</p></div><div class="filters" role="group" aria-label="Filter stays">${['All Stays','Couples','Families','Groups','Large Groups'].map((f,i)=>`<button type="button" data-filter="${f}" class="${i===0?'active':''}">${f}</button>`).join('')}</div></div><div class="room-grid" id="room-grid">${rooms.map(card).join('')}</div><div class="compare"><div><span class="eyebrow">FIND YOUR FIT</span><h2>Compare Your Stay</h2><p>Choose two or three accommodations to see their details side by side.</p></div><div class="compare-controls">${rooms.map(r=>`<label><input type="checkbox" value="${r.slug}"><span>${r.name}</span></label>`).join('')}</div><div id="comparison" aria-live="polite"></div></div></section>`);document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelector('.filters .active')?.classList.remove('active');b.classList.add('active');let f=b.dataset.filter;$('#room-grid').innerHTML=rooms.filter(r=>f==='All Stays'||r.tags.includes(f)).map(card).join('')});document.querySelectorAll('.compare-controls input').forEach(i=>i.onchange=()=>{let chosen=[...document.querySelectorAll('.compare-controls input:checked')];if(chosen.length>3){i.checked=false;chosen=chosen.filter(x=>x!==i)}$('#comparison').innerHTML=chosen.length<2?'<p class="hint">Select at least two stays to compare.</p>':`<div class="comparison-grid">${chosen.map(x=>{let r=rooms.find(y=>y.slug===x.value);return `<div><img src="${img(r)}" alt="${r.name}"><h3>${r.name}</h3><p>${r.category}</p><p>${r.capacity?`Up to ${r.capacity} guests`:'Capacity on request'}</p><p>${r.price?`${peso(r.price)} / night`:'Rate on request'}</p><p>Verified amenities: inquire with resort</p><a class="text-link" href="${href(r)}">SELECT ROOM ${svg('arrow')}</a></div>`}).join('')}</div>`})}
function detail(r){document.title=`${r.name} | Aquapoint Beach Resort`;shell(`<div class="breadcrumbs"><a href="/">Home</a><span>/</span><a href="/rooms/">Rooms</a><span>/</span>${r.name}</div><section class="detail-image"><img src="${img(r)}" alt="${r.name} accommodation at Aquapoint Beach Resort"><a href="${img(r)}" target="_blank" rel="noopener" class="photo-link">VIEW PHOTO ${svg('arrow')}</a></section><section class="detail-layout"><div class="detail-copy"><span class="eyebrow">AQUAPOINT BEACH RESORT · ${r.category.toUpperCase()}</span><h1>${r.name}</h1><p class="detail-capacity">${svg('users')} ${r.capacity?`Up to ${r.capacity} Guests`:'Capacity available on request'}</p><p class="description">${r.description}</p><div class="detail-divider"></div><h2>About this stay</h2><p>Make this space your home base for a relaxing escape by the sea. Contact the resort to confirm availability and the amenities for your dates.</p><div class="detail-divider"></div><h2>Good to know</h2><p>Accommodation rates are shown per night. Amenities and availability are confirmed during reservation.</p></div><aside class="booking-panel"><span class="eyebrow">YOUR STAY</span><div class="panel-price">${r.price?`<strong>${peso(r.price)}</strong><span> / night</span>`:'<strong>Rate on request</strong>'}</div><p>${r.capacity?`Designed for up to ${r.capacity} guests.`:'Please inquire for the villa’s guest capacity and rate.'}</p><form id="quick-form"><div class="date-pair"><label>CHECK-IN<input type="date" name="checkin" required></label><label>CHECK-OUT<input type="date" name="checkout" required></label></div><button class="button dark full" type="submit">CHECK AVAILABILITY ${svg('arrow')}</button></form><a class="text-link panel-link" href="${book(r)}">${r.reserve.toUpperCase()} ${svg('arrow')}</a><small>Availability and final rates are confirmed by resort staff.</small></aside></section><div class="mobile-book"><span>${r.price?`${peso(r.price)} <small>/ night</small>`:'Rate on request'}</span><a href="${book(r)}">RESERVE ${svg('arrow')}</a></div><section class="more-rooms"><div class="section-head"><div><span class="eyebrow">KEEP EXPLORING</span><h2>More ways to stay</h2></div><a href="/rooms/">ALL ROOMS ${svg('arrow')}</a></div><div class="room-grid">${rooms.filter(x=>x.slug!==r.slug).slice(0,3).map(card).join('')}</div></section>`);$('#quick-form').onsubmit=e=>{e.preventDefault();let data=new FormData(e.currentTarget),p=new URLSearchParams({room:r.slug,checkin:data.get('checkin'),checkout:data.get('checkout')});location.href=`/booking/?${p}`}}
function booking(){let params=new URLSearchParams(location.search),selected=rooms.find(r=>r.slug===params.get('room'))||rooms[0];shell(`<section class="page-hero booking-hero"><span class="eyebrow">PLAN YOUR ESCAPE</span><h1>Reservation<br><em>Details</em></h1><p>Build an estimate for your stay. Resort staff will confirm availability and the final reservation.</p></section><section class="booking-layout"><form id="booking-form" class="reservation-form"><h2>Your stay</h2><div class="form-grid"><label class="wide">ACCOMMODATION<select name="room">${rooms.map(r=>`<option value="${r.slug}" ${r.slug===selected.slug?'selected':''}>${r.name}</option>`).join('')}</select></label><label>CHECK-IN<input type="date" name="checkin" value="${params.get('checkin')||''}" required></label><label>CHECK-OUT<input type="date" name="checkout" value="${params.get('checkout')||''}" required></label><label>ADULTS<input type="number" name="adults" min="1" value="2" required></label><label>CHILDREN<input type="number" name="children" min="0" value="0" required></label></div><div id="capacity-message" aria-live="polite"></div><p class="form-note">This is an estimate only. Availability and final details need to be confirmed with the resort.</p><button type="button" id="copy-request" class="button dark">COPY RESERVATION DETAILS ${svg('arrow')}</button><span id="copy-status" role="status"></span></form><aside class="summary"><span class="eyebrow">YOUR ESTIMATE</span><h2>Stay Summary</h2><img id="summary-image" src="${img(selected)}" alt="${selected.name}"><dl><div><dt>Selected Accommodation</dt><dd id="s-room"></dd></div><div><dt>Check-in</dt><dd id="s-in">—</dd></div><div><dt>Check-out</dt><dd id="s-out">—</dd></div><div><dt>Number of Nights</dt><dd id="s-nights">—</dd></div><div><dt>Adults</dt><dd id="s-adults">2</dd></div><div><dt>Children</dt><dd id="s-children">0</dd></div><div><dt>Room Rate</dt><dd id="s-rate"></dd></div></dl><div class="summary-total"><span>Estimated Total</span><strong id="s-total"></strong></div><small>No undefined fees included. Staff confirms the reservation.</small></aside></section>`);const form=$('#booking-form');function update(){let d=new FormData(form),r=rooms.find(x=>x.slug===d.get('room')),a=Number(d.get('adults')),c=Number(d.get('children')),n=Math.round((new Date(d.get('checkout'))-new Date(d.get('checkin')))/86400000),valid=Number.isFinite(n)&&n>0;$('#s-room').textContent=r.name;$('#summary-image').src=img(r);$('#summary-image').alt=r.name;$('#s-in').textContent=d.get('checkin')||'—';$('#s-out').textContent=d.get('checkout')||'—';$('#s-nights').textContent=valid?n:'—';$('#s-adults').textContent=a;$('#s-children').textContent=c;$('#s-rate').textContent=r.price?`${peso(r.price)} / night`:'On request';$('#s-total').textContent=r.price&&valid?peso(r.price*n):'On request';let msg=$('#capacity-message');if(r.capacity&&a+c>r.capacity){let options=rooms.filter(x=>x.capacity&&x.capacity>=a+c&&x.slug!==r.slug).sort((x,y)=>x.capacity-y.capacity);msg.innerHTML=`<div class="capacity-warning"><strong>This room accommodates up to ${r.capacity} guests.</strong><p>${options.length?'View larger rooms suited to your party:':'Please contact the resort about a larger group stay.'}</p>${options.map(x=>`<a href="${href(x)}">${x.name} · up to ${x.capacity} guests ${svg('arrow')}</a>`).join('')}${!options.length?`<a href="${href(rooms[8])}">Ask about the Luxury Villa ${svg('arrow')}</a>`:''}</div>`}else msg.innerHTML='';return {r,a,c,n,valid,over:r.capacity&&a+c>r.capacity,d}}form.addEventListener('input',update);form.addEventListener('change',update);update();$('#copy-request').onclick=async()=>{let x=update();if(!x.valid){$('#copy-status').textContent='Enter a check-in and later check-out date first.';return}if(x.over){$('#copy-status').textContent='Choose a room that fits your group first.';return}let s=`Aquapoint Beach Resort reservation inquiry\nAccommodation: ${x.r.name}\nCheck-in: ${x.d.get('checkin')}\nCheck-out: ${x.d.get('checkout')}\nNights: ${x.n}\nAdults: ${x.a}\nChildren: ${x.c}\nRoom rate: ${x.r.price?`${peso(x.r.price)} / night`:'On request'}\nEstimated total: ${x.r.price?peso(x.r.price*x.n):'On request'}\nPlease confirm availability and final details.`;try{await navigator.clipboard.writeText(s);$('#copy-status').textContent='Reservation details copied. Share them with the resort to inquire.'}catch{$('#copy-status').textContent='Copy is unavailable in this browser.'}}}
let path=location.pathname.replace(/\/+$/,'')||'/';if(path==='/')home();else if(path==='/rooms')listing();else if(path==='/booking')booking();else{let match=path.match(/^\/rooms\/([^/]+)$/),room=match&&rooms.find(r=>r.slug===match[1]);room?detail(room):shell('<section class="page-hero"><h1>Page not found</h1><a class="button dark" href="/rooms/">EXPLORE ROOMS</a></section>')}
